#include <vector>
#include <queue>

class Solution {
public:
    int countConnectedSubgraphs(std::vector<int>& nums, std::vector<std::vector<int>>& edges) {
        int n = nums.size();
        std::vector<std::vector<int>> g(n);
        for (const auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        int ans = 0;
        int totalSub = 1 << n;
        for (int sub = 1; sub < totalSub; ++sub) {
            int nodeSum = 0;
            int start = -1;
            for (int i = 0; i < n; ++i) {
                if ((sub >> i) & 1) {
                    nodeSum += nums[i];
                    if (start == -1) start = i;
                }
            }
            if (nodeSum % 2 != 0) continue;
            int visitedMask = 1 << start;
            std::queue<int> q;
            q.push(start);
            while (!q.empty()) {
                int curr = q.front();
                q.pop();
                for (int nxt : g[curr]) {
                    if (((sub >> nxt) & 1) && !((visitedMask >> nxt) & 1)) {
                        visitedMask |= (1 << nxt);
                        q.push(nxt);
                    }
                }
            }
            if (visitedMask == sub) ans++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countConnectedSubgraphs(int[] nums, int[][] edges) {
        int n = nums.length;
        List<List<Integer>> g = new ArrayList<>();
        for (int i = 0; i < n; i++) g.add(new ArrayList<>());
        for (int[] e : edges) {
            g.get(e[0]).add(e[1]);
            g.get(e[1]).add(e[0]);
        }
        int ans = 0;
        int totalSub = 1 << n;
        for (int sub = 1; sub < totalSub; sub++) {
            int nodeSum = 0;
            int start = -1;
            for (int i = 0; i < n; i++) {
                if (((sub >> i) & 1) == 1) {
                    nodeSum += nums[i];
                    if (start == -1) start = i;
                }
            }
            if (nodeSum % 2 != 0) continue;
            int visitedMask = 1 << start;
            Queue<Integer> q = new LinkedList<>();
            q.offer(start);
            while (!q.isEmpty()) {
                int curr = q.poll();
                for (int nxt : g.get(curr)) {
                    if (((sub >> nxt) & 1) == 1 && ((visitedMask >> nxt) & 1) == 0) {
                        visitedMask |= (1 << nxt);
                        q.offer(nxt);
                    }
                }
            }
            if (visitedMask == sub) ans++;
        }
        return ans;
    }
}

